import logging
from typing import List, Optional, Union, Dict
from taf.ul.chart.throughput import throughput
from taf.ul.stream.aasyslog.exceptions import UnexpectedCellsThroughputError
from taf.analyzer.aasyslog_throughput import aasyslog_throughput

__all__ = ["get_aasyslog_throughput", "check_aasyslog_throughput", "check_bi_aasyslog_throughput"]

aatput = aasyslog_throughput()
tput_chart = throughput()


def get_aasyslog_throughput(direction: str,
                            log_path: str,
                            cells: List,
                            ca: Optional[bool] = False):
    direction = direction.lower()
    if direction == "ul":
        raw_throughput, records = get_ul_aasyslog_tput(
            log_path=log_path, cells=cells, ca=ca
        )
    elif direction == "dl":
        raw_throughput, records = get_dl_aasyslog_tput(
            log_path=log_path, cells=cells, ca=ca
        )
    else:
        raise AttributeError(
            "Wrong direction: {}, should be UL or DL.".format(direction)
        )
    return raw_throughput, records


def get_ul_aasyslog_tput(log_path: str, cells: List[Union[str, int]] = None,
                         ca: Optional[bool] = False):
    record_output = {}
    if ca:
        alias = "ulcatp{}".format(log_path)
        aatput.create_ca_uplink_throughput(
            cells=cells, log=log_path, alias=alias, throughput_records_output=record_output
        )
    else:
        alias = "ultp{}".format(log_path)
        aatput.create_uplink_throughput(
            cells=cells, log=log_path, alias=alias, throughput_records_output=record_output
        )
    aatput.analyze(throughputs=[alias])
    return aatput.get_throughput(throughput=alias), record_output


def get_dl_aasyslog_tput(log_path: str, cells: List[Union[str, int]] = None,
                         ca: Optional[bool] = False):
    record_output = {}
    if ca:
        alias = "dlcatp{}".format(log_path)
        aatput.create_ca_downlink_throughput(
            cells=cells, log=log_path, alias=alias, throughput_records_output=record_output
        )
    else:
        alias = "dltp{}".format(log_path)
        aatput.create_downlink_throughput(
            cells=cells, log=log_path, alias=alias, throughput_records_output=record_output
        )
    aatput.analyze(throughputs=[alias])
    return aatput.get_throughput(throughput=alias), record_output


def check_aasyslog_throughput(
        raw_throughput: List[Dict],
        records: Dict,
        direction: str,
        cells: List,
        theoretical_throughput: str,
        average_tolerance: Union[float, int] = 0.95,
        minimum_tolerance: Union[float, int] = 0.85,
        ca: Optional[bool] = False,
        output_dir: Optional[str] = None,
        customized_chart_file_name: Optional[str] = None,
        enable_chart_generation=True
):
    """
    used for checking single direction throughput data from aasyslog file.
    Can also be used for analyze each direction data individually in bi-direction traffic.

    :param raw_throughput: dict of list
    :param records: dict
    :param direction: (str) "UL" / "DL"
    :param cells: (list) list of on taffic cell id.  E.G: ['16385', '16386']
    :param theoretical_throughput: (str) target throughput value.(theory value) unit in Mbps!! E.G 2048.0
    :param average_tolerance: (str) acceptable percent. Default use 95%.
                               use in varify: tput > theoretical_throughput * average_tolerance
    :param minimum_tolerance: (str) minimum percentage, default use 85%.
    :param ca: (bool) ca in configuration.
    :param output_dir: (str) image file output directory, if None, will use current dir.
    :return:
    """
    tput = transfer_aasyslog_tput_format(raw_throughput)
    logging.info("Getting origin tput result: {}".format(raw_throughput))
    if enable_chart_generation:
        try:
            tput_chart.generate(
                records=records,
                direction=direction,
                ca=ca,
                theoretical_throughput=theoretical_throughput,
                average_tolerance=average_tolerance,
                minimum_tolerance=minimum_tolerance,
                output_dir=output_dir,
                log_name_prefix=customized_chart_file_name,
                time_interval=min([i["min_time_interval"] for i in raw_throughput]),
            )
        except Exception as err:
            logging.exception("Can't generate {} image. {}".format(direction, err))
    if ca:
        _validate_ca_throughput(tput, theoretical_throughput, average_tolerance, minimum_tolerance,
                                direction, raw_throughput)
    else:
        _validate_without_ca_throughput(cells, tput, theoretical_throughput, average_tolerance, minimum_tolerance,
                                        direction, raw_throughput)


def _validate_ca_throughput(tput,
                            theoretical_throughput,
                            average_tolerance,
                            minimum_tolerance,
                            direction,
                            raw_throughput):
    try:
        _validate_tput_values(tput[None], theoretical_throughput, average_tolerance, minimum_tolerance, "all")
    except ValueError as err:
        raise UnexpectedCellsThroughputError(
            msg="Failed at {} during checking CA cells, err:".format(direction, err),
            throughput=raw_throughput
        )


def _validate_without_ca_throughput(cells,
                                    tput,
                                    theoretical_throughput,
                                    average_tolerance,
                                    minimum_tolerance,
                                    direction,
                                    raw_throughput):
    cell_failed = False
    error_print = []
    for cid in cells:
        try:
            _validate_tput_values(tput[str(cid)], theoretical_throughput,
                                  average_tolerance, minimum_tolerance, str(cid))
        except ValueError as err:
            error_print.append("failed at {} on Cell:{}, err: {}".format(direction, cid, err))
            cell_failed = True
    else:
        if cell_failed:
            raise UnexpectedCellsThroughputError(
                msg="Failed during checking all cell. Errors below: {}".format("\n".join(error_print)),
                throughput=raw_throughput
            )


def check_bi_aasyslog_throughput(log_path: str,
                                 cells: List[Union[str, int]],
                                 ul_theoretical_throughput: str,
                                 dl_theoretical_throughput: str,
                                 average_tolerance: Union[float, int] = 0.95,
                                 minimum_tolerance: Union[float, int] = 0.85,
                                 ca: Optional[bool] = False,
                                 output_dir: Optional[str] = None,
                                 customized_chart_file_name: Optional[str] = None,
                                 enable_chart_generation: Optional[bool] = True):
    """
    used for checking bi-direction throughput data from aasyslog file.

    :param log_path: (str) full path of aasyslog file
    :param cells: (list) list of on taffic cell id.  E.G: ['16385', '16386']
    :param ul_theoretical_throughput: (str) target throughput value.(theory value) unit in Mbps!! E.G 2048.0
    :param dl_theoretical_throughput: (str) target throughput value.(theory value) unit in Mbps!! E.G 2048.0
    :param average_tolerance: (str) acceptable percent. Default use 95%.
                               use in varify: ultput > ul_theoretical_throughput * average_tolerance
                                              dltput > dl_theoretical_throughput * average_tolerance
    :param minimum_tolerance: (str) minimum percentage, default use 85%.
    :param ca: (bool) ca in configuration.
    :param output_dir: (str) image file output directory, if None, will use current dir.
    :return:
    """
    raw_throughput, ul_origin_record, dl_origin_record = get_bi_direction_aasyslog_tput(
        log_path=log_path,
        cells=cells,
        ca=ca
    )
    ultp = transfer_aasyslog_tput_format(raw_throughput["ul"])
    dltp = transfer_aasyslog_tput_format(raw_throughput["dl"])
    logging.info("Getting origin tput result: {}".format(raw_throughput))
    if enable_chart_generation:
        try:
            tput_chart.generate(
                records=ul_origin_record,
                direction="ul",
                ca=ca,
                theoretical_throughput=ul_theoretical_throughput,
                average_tolerance=average_tolerance,
                minimum_tolerance=minimum_tolerance,
                output_dir=output_dir,
                log_name_prefix=customized_chart_file_name,
                time_interval=min([i["min_time_interval"] for i in raw_throughput["ul"]]),
            )
        except Exception as err:
            logging.exception("Can't generate UL image. {}".format(err))
        try:
            tput_chart.generate(
                records=dl_origin_record,
                direction="dl",
                ca=ca,
                theoretical_throughput=dl_theoretical_throughput,
                average_tolerance=average_tolerance,
                minimum_tolerance=minimum_tolerance,
                output_dir=output_dir,
                log_name_prefix=customized_chart_file_name,
                time_interval=min([i["min_time_interval"] for i in raw_throughput["dl"]]),
            )
        except Exception as err:
            logging.exception("Can't generate DL image. {}".format(err))
    if ca:
        _validata_bi_ca_throughput(ultp, dltp, ul_theoretical_throughput, dl_theoretical_throughput,
                                   average_tolerance, minimum_tolerance, raw_throughput)

    else:
        _validata_bi_without_ca_throughput(cells, ultp, dltp, ul_theoretical_throughput, dl_theoretical_throughput,
                                           average_tolerance, minimum_tolerance, raw_throughput)


def _validata_bi_ca_throughput(ultp, dltp, ul_theoretical_throughput, dl_theoretical_throughput, average_tolerance,
                               minimum_tolerance, raw_throughput):
    ul_failed = False
    dl_failed = False
    try:
        logging.info("Start checking ul throughput in bi-direction check.")
        _validate_tput_values(ultp[None], ul_theoretical_throughput, average_tolerance, minimum_tolerance, "all")
    except ValueError as err:
        logging.exception(err)
        ul_failed = True
    try:
        logging.info("Start checking dl throughput in bi-direction check.")
        _validate_tput_values(dltp[None], dl_theoretical_throughput, average_tolerance, minimum_tolerance, "all")
    except ValueError as err:
        logging.exception(err)
        dl_failed = True
    if ul_failed and dl_failed:
        raise UnexpectedCellsThroughputError(
            msg="Failed at {} during bi-direction check.".format("UL and DL"),
            throughput=raw_throughput,
        )
    if ul_failed:
        raise UnexpectedCellsThroughputError(
            msg="Failed at {} during bi-direction check.".format("UL"),
            throughput=raw_throughput
        )
    if dl_failed:
        raise UnexpectedCellsThroughputError(
            msg="Failed at {} during bi-direction check.".format("DL"),
            throughput=raw_throughput
        )


def _validata_bi_without_ca_throughput(cells, ultp, dltp, ul_theoretical_throughput, dl_theoretical_throughput,
                                       average_tolerance, minimum_tolerance, raw_throughput):
    bi_failed = False
    error_print = []
    for cid in cells:
        ul_failed = False
        dl_failed = False
        try:
            logging.info("Start checking ul throughput in bi-direction check.")
            _validate_tput_values(ultp[str(cid)], ul_theoretical_throughput, average_tolerance, minimum_tolerance,
                                  str(cid))
        except ValueError as err:
            logging.exception(err)
            ul_failed = True
        try:
            logging.info("Start checking dl throughput in bi-direction check.")
            _validate_tput_values(dltp[str(cid)], dl_theoretical_throughput,
                                  average_tolerance, minimum_tolerance, str(cid))
        except ValueError as err:
            logging.exception(err)
            ul_failed = True

        if ul_failed and dl_failed:
            error_print.append("Failed at {} direction during bi-direction check on cell: {}.".format("UL and DL",
                                                                                                      cid))
        if ul_failed:
            error_print.append("Failed at {} direction during bi-direction check on cell: {}.".format("UL", cid))
            bi_failed = True

        if dl_failed:
            error_print.append("Failed at {} direction during bi-direction check on cell: {}.".format("DL", cid))
            bi_failed = True
    else:
        if bi_failed:
            raise UnexpectedCellsThroughputError(
                msg="Failed during bi_direction check. {}".format("\n".join(error_print)),
                throughput=raw_throughput
            )


def get_bi_direction_aasyslog_tput(log_path: str,
                                   cells: List[Union[str, int]] = None,
                                   ca: Optional[bool] = False):
    ul_record_output = {}
    dl_record_output = {}
    if ca:
        ulalias = "ulcatp{}".format(log_path)
        dlalias = "dlcatp{}".format(log_path)
        aatput.create_ca_uplink_throughput(
            cells=cells, alias=ulalias, throughput_records_output=ul_record_output
        )
        aatput.create_ca_downlink_throughput(
            cells=cells, alias=dlalias, throughput_records_output=dl_record_output
        )
    else:
        ulalias = "ultp{}".format(log_path)
        dlalias = "dltp{}".format(log_path)
        aatput.create_uplink_throughput(
            cells=cells, alias=ulalias, throughput_records_output=ul_record_output
        )
        aatput.create_downlink_throughput(
            cells=cells, alias=dlalias, throughput_records_output=dl_record_output
        )
    aatput.analyze(throughputs=[ulalias, dlalias], log=log_path)
    raw_throughput = {"ul": aatput.get_throughput(throughput=ulalias),
                      "dl": aatput.get_throughput(throughput=dlalias)}
    return raw_throughput, ul_record_output, dl_record_output


def _validate_tput_values(tput: Dict,
                          theoretical_throughput: Union[int, float, str],
                          average_tolerance: Union[str, int, float],
                          minimum_tolerance: Union[str, int, float],
                          cell_id: Union[int, str]):
    min_tput = tput["minimum"]
    avg_tput = tput["average"]
    avg_percent = translate_percentage(average_tolerance)
    minimum_tolerance = translate_percentage(minimum_tolerance)
    min_target = float(theoretical_throughput) * minimum_tolerance
    avg_target = float(theoretical_throughput) * avg_percent
    _validate_tput_with_avg_target(avg_target, avg_tput, cell_id, theoretical_throughput, avg_percent)
    _validate_tput_with_min_target(min_target, min_tput, cell_id, theoretical_throughput)


def _validate_tput_with_avg_target(avg_target, avg_tput, cell_id, theoretical_throughput, avg_percent):
    if avg_target < 0:
        avg_target = -avg_target
        logging.info(
            "Validating cell {} average throughput, should lower than {}Mbps ({}Mbps * {})".format(
                cell_id, avg_target, theoretical_throughput, avg_percent
            )
        )
        if not avg_tput <= avg_target:
            raise ValueError("AVG is {}Mbps, Higher than{}Mbps".format(avg_tput, avg_target))
        else:
            logging.info("AVG is {}Mbps, check pass.".format(avg_tput))
    else:
        logging.info(
            "Validating cell {} average throughput, should not lower than {}Mbps ({}Mbps * {})".format(
                cell_id, avg_target, theoretical_throughput, avg_percent
            )
        )
        if not avg_tput >= avg_target:
            raise ValueError("AVG is {}Mbps, lower than{}Mbps".format(avg_tput, avg_target))
        else:
            logging.info("AVG is {}Mbps, check pass.".format(avg_tput))


def _validate_tput_with_min_target(min_target, min_tput, cell_id, theoretical_throughput):
    if min_target < 0:
        min_target = -min_target
        logging.info("Validating cell {} minimum tput, should lower than {}Mbps ({}Mbps * minimum_tolerance)".format(
            cell_id, min_target, theoretical_throughput
        ))
        if not min_tput < min_target:
            raise ValueError("min is {}Mbps, higher than {}Mbps".format(min_tput, min_target))
        else:
            logging.info("min is {}Mbps, check pass.".format(min_tput))
    else:
        logging.info("Validating cell {} minimum tput, should not "
                     "lower than {}Mbps ({}Mbps * minimum_tolerance)".format(cell_id, min_target,
                                                                             theoretical_throughput))
        if not min_tput >= min_target:
            raise ValueError("min is {}Mbps, lower than {}Mbps".format(min_tput, min_target))
        else:
            logging.info("min is {}Mbps, check pass.".format(min_tput))


def __convert_mbps_to_bytes_with_time_interval(tput, time_interval):
    return float(tput) / 8 * 1000 * 1000 * float(time_interval)


def __convert_bytes_to_mbps_with_time_interval(tput, time_interval):
    return int(float(tput) * 8 / 1000 / 1000 / float(time_interval))


def _get_pic_data(origin_list):
    tput_list = []
    time_list = []
    for data in origin_list:
        tput = __convert_bytes_to_mbps_with_time_interval(tput=data['throughput'], time_interval=1.024)
        tput_list.append(tput)
        time_list.append(data['record_time'])
    return time_list, tput_list


def _get_general_pic_data(origin_list, count):
    general_tput_list = [0] * count
    cells = list(dict.keys(origin_list))
    for cnt in range(0, count):
        for cid in cells:
            tput = __convert_bytes_to_mbps_with_time_interval(
                tput=origin_list[cid][cnt]['throughput'], time_interval=1.024
            )
            general_tput_list[cnt] = general_tput_list[cnt] + tput
    return general_tput_list


def transfer_aasyslog_tput_format(raw_throughput):
    translated = {}
    for data in raw_throughput:
        translated[data["cellid"]] = data
    return translated


def translate_percentage(origin_percent):
    percent = str(origin_percent)
    if "%" in percent:
        target_percent = float(percent.replace("%", "")) / 100.0
    else:
        target_percent = float(percent)
    return target_percent
